mapper.sql:
WITH FORM AS ( SELECT WF.WK_ID, WF.WK_NM, L.LEFRM_ID, L.LEFRM_NM, L.DOC_ID FROM OCUOC_OCRWF_M WF JOIN OCUOC_OCRWL_L WL ON WL.WK_ID = WF.WK_ID JOIN OCUOC_LEFRM_M L ON L.LEFRM_ID = WL.LEFRM_ID
AND WF.WK_ID = #{wk_id}
AND WF.WK_NM LIKE '%' || #{ocr_work_nm} || '%'
AND 1 = 0
), DOCS AS ( SELECT DISTINCT FM.LEFRM_ID, O.DOC_ID FROM (SELECT DISTINCT LEFRM_ID, DOC_ID FROM FORM) FM JOIN OCUOC_OCRDO_L O ON (O.DOC_TYP_CD = FM.DOC_ID OR O.DOC_TYP_CD = 'KJB_' || FM.DOC_ID) WHERE NVL(LOWER(O.DOC_STAT_CD), ' ') NOT IN ('failed', 'canceled') ), ITEM AS ( SELECT D.LEFRM_ID, 'F' AS ITEM_TYPE, F.FILD_KEY FROM DOCS D JOIN OCUOC_OCRDF_L F ON F.DOC_ID = D.DOC_ID UNION SELECT D.LEFRM_ID, 'C', R.FILD_KEY FROM DOCS D JOIN OCUOC_OCRDT_L T ON T.DOC_ID = D.DOC_ID JOIN OCUOC_OCRTR_L R ON R.TBL_ID = T.TBL_ID ), RW AS ( SELECT FM.WK_ID, FM.WK_NM, FM.LEFRM_ID, FM.LEFRM_NM, FM.DOC_ID, I.ITEM_TYPE, I.FILD_KEY FROM FORM FM JOIN ITEM I ON I.LEFRM_ID = FM.LEFRM_ID UNION SELECT FM.WK_ID, FM.WK_NM, FM.LEFRM_ID, FM.LEFRM_NM, FM.DOC_ID, NULL, P.FILD_KEY FROM FORM FM JOIN OCUOC_LFMAP_L P ON P.WK_ID = FM.WK_ID AND P.LEFRM_ID = FM.LEFRM_ID WHERE NOT EXISTS (SELECT 1 FROM ITEM I WHERE I.LEFRM_ID = P.LEFRM_ID AND I.FILD_KEY = P.FILD_KEY) )

mapper.select:
/* [OCR업무사용신청] 목록 - selectUsageList */
SELECT RW.WK_ID AS "wkId" , RW.WK_NM AS "wkNm" , RW.LEFRM_ID AS "lefrmId" , RW.LEFRM_NM AS "ocrDoc" , RW.DOC_ID AS "ocrCode" , RW.ITEM_TYPE AS "itemType" , RW.FILD_KEY AS "readItem" , NVL(P.FILD_NM, RW.FILD_KEY) AS "readItemNm" , P.SCN_NO AS "dispNumber" , P.MAPP_INFO AS "mappingInfo" , P.DISP_ORD AS "dispOrd" , CASE WHEN P.FILD_KEY IS NULL THEN 'N' ELSE 'Y' END AS "savedYn"
ORDER BY RW.WK_NM, RW.LEFRM_NM, NVL(P.DISP_ORD, 99999), RW.ITEM_TYPE, RW.FILD_KEY OFFSET #{offset} ROWS FETCH NEXT #{limit} ROWS ONLY

/* [OCR업무사용신청] 업무 검색 팝업 - selectTaskList */ SELECT WF.WK_ID AS "wkId" , WF.WK_NM AS "wkNm" , WF.WK_STAT_CD AS "wkStatCd" , (SELECT COUNT(*) FROM OCUOC_OCRWL_L WL WHERE WL.WK_ID = WF.WK_ID) AS "formCnt" FROM OCUOC_OCRWF_M WF
AND WF.WK_NM LIKE '%' || #{keyword} || '%'
ORDER BY WF.WK_NM FETCH FIRST 200 ROWS ONLY
